    diamond_kernel = set()
    for dr in range(-radius, radius+1):
        for dc in range(-radius, radius+1):
            if abs(dr) + abs(dc) <= radius:
                diamond_kernel.add((dr, dc))

    diamond_union = [[False] * cols for _ in range(rows)]
    centers = []  # Track where 2s are (these stay 2)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                centers.append((r, c))
                # Mark diamond area
                for dr, dc in diamond_kernel:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        diamond_union[nr][nc] = True

    # Apply output
    for r in range(rows):
        for c in range(cols):
            if (r, c) in centers:
